use super::*;
use crate::clients::router::{ChatParams, RouterClient, StreamSink};
use crate::types::message::{AssistantMessage, empty_assistant};
use async_trait::async_trait;
use futures_util::{SinkExt, StreamExt};
use serde_json::json;
use std::sync::{Arc, Mutex};
use tokio::sync::{oneshot, watch};

const MEMORY_TEXT: &str =
    "<memory bank=\"synthetic-atlas\">\n- Atlas deploys with ember.\n</memory>";

// Generated by the production Context renderer/assembly APIs; see the fixture README.
// Ordinary Harness tests only consume tracked bytes, never execute a generator.
fn native_context_fixture() -> Value {
    serde_json::from_str(include_str!(
        "../../tests/fixtures/generation_capture/native-context.json"
    ))
    .unwrap()
}

struct Sink;
#[async_trait]
impl StreamSink for Sink {
    async fn on_update(&self, _: &AssistantMessage) {}
}

fn params(fact: &str) -> ChatParams {
    ChatParams {
        source_hints: SourceHints::default(),
        turn_id: "synthetic-turn".into(),
        step: 7,
        request_id: "opaque:same-retry".into(),
        session_id: "synthetic-session".into(),
        model: "synthetic".into(),
        provider: None,
        system_prompt: Some(format!("policy\n\n- {fact}")),
        system_sections: Some(json!([{"text":"policy"},{"text":format!("- {fact}")}])),
        messages: vec![json!({"role":"custom", "content":[
            {"type":"file","attachment_id":"never-in-witness"},
            {"type":"text","text":format!("mutated\n* {fact}")},
            {"type":"image","attachment_id":"private-link","data":"synthetic-bytes"}
        ]})],
        tools: vec![],
        response_format: None,
        max_output_tokens: None,
        thinking_level: None,
        provider_options: None,
        cache_intent: None,
    }
}

/// Real SDK WebSocket loopback, not an engine or provider. Captures the actual
/// invokefunction payload handed to router::chat and serialized registration.
async fn loopback(observed: bool, mode: &str) -> (Vec<Value>, Vec<Value>, Vec<String>) {
    loopback_with_capture(observed, mode, CaptureMode::SyntheticIsolation).await
}

async fn loopback_with_capture(
    observed: bool,
    mode: &str,
    capture_mode: CaptureMode,
) -> (Vec<Value>, Vec<Value>, Vec<String>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let url = format!("ws://{}", listener.local_addr().unwrap());
    let memory_fixture = mode.starts_with("origin_memory_");
    let turn_id = if memory_fixture {
        "control-r13"
    } else {
        "synthetic-turn"
    };
    let step = if memory_fixture { 0 } else { 7 };
    let session_id = if memory_fixture {
        format!("e2e_control-r13-{mode}")
    } else if mode.starts_with("origin_") {
        format!("synthetic-session-{mode}")
    } else {
        "synthetic-session".into()
    };
    let server_session = session_id.clone();
    let calls = Arc::new(Mutex::new(Vec::new()));
    let registrations = Arc::new(Mutex::new(Vec::new()));
    let seen = calls.clone();
    let regs = registrations.clone();
    let outcome_mode = mode.to_string();
    let mode = mode.to_string();
    let (ready_tx, ready_rx) = oneshot::channel();
    let (registered_tx, registered_rx) = oneshot::channel();
    let server = tokio::spawn(async move {
        let (tcp, _) = listener.accept().await.unwrap();
        let mut socket = tokio_tungstenite::accept_async(tcp).await.unwrap();
        socket.send(tokio_tungstenite::tungstenite::Message::Text(json!({
            "type":"workerregistered","worker_id":"synthetic-worker","features":["observe.v2"]
        }).to_string().into())).await.unwrap();
        ready_tx.send(()).unwrap();
        let mut registered_tx = Some(registered_tx);
        let mut observer_acks = 0;
        let initial_turn = json!({
            "session_id":server_session, "turn_id":turn_id,
            "status":"running", "step":step, "turn_count":2, "depth":0,
            "options":{"model":"synthetic", "max_turns":16,
                "functions":{"allow":[], "deny":[], "expose":"agent_call"}},
            "created_at":1, "updated_at":1
        });
        let mut stored_turn = initial_turn.clone();
        let mut notices: Vec<Value> = Vec::new();
        let mut generation_round = 0usize;
        // This transcript origin deliberately survives all idempotent appends.
        let stale_origin = json!({"source":"harness", "generation_id":"stale-generation"});
        let stream_mode = mode.clone();
        let streams = tokio::spawn(async move {
            while let Ok((tcp, _)) = listener.accept().await {
                let stream_mode = stream_mode.clone();
                tokio::spawn(async move {
                    let mut stream = tokio_tungstenite::accept_async(tcp).await.unwrap();
                    if stream_mode == "cancel" {
                        while stream.next().await.is_some() {}
                        return;
                    }
                    let mut message = empty_assistant("synthetic", "synthetic");
                    message.stop_reason = crate::types::event::StopReason::End;
                    let done = json!({"type":"done","message": message});
                    let _ = stream
                        .send(tokio_tungstenite::tungstenite::Message::Text(
                            done.to_string().into(),
                        ))
                        .await;
                    let _ = stream.close(None).await;
                });
            }
        });
        while let Some(Ok(frame)) = socket.next().await {
            let Ok(text) = frame.to_text() else { continue };
            let Ok(message) = serde_json::from_str::<Value>(text) else {
                continue;
            };
            if message["type"] == "observerack" {
                regs.lock().unwrap().push(message.clone());
                observer_acks += 1;
                if observer_acks == 9
                    && let Some(tx) = registered_tx.take()
                {
                    let _ = tx.send(());
                }
                continue;
            }
            if message["type"] == "registerfunction" {
                let id = message["id"].as_str().unwrap();
                regs.lock().unwrap().push(message.clone());
                // A forged remote snapshot must not override the local mode.
                let observers = if mode.starts_with("origin_")
                    && id == crate::hooks::ON_PRE_GENERATE_FN
                {
                    json!([{"id":"source-observer", "target": if mode.ends_with("forged") && !mode.ends_with("owner_forged") {"synthetic::forger"} else {"memory::hook::pre-generate"},
                        "args":{"timeout_ms":1000}, "filters":{}, "capture":["input","output","caller"], "on":"success"}])
                } else if mode == "forged_snapshot"
                    && [REQUEST, RESPONSE, MEMORY_RECEIPT].contains(&id)
                {
                    json!([{"id":"forged-snapshot", "target":"synthetic::collector"}])
                } else {
                    json!([])
                };
                let ack =
                    json!({"type":"functionregistered","id":id,"revision":1,"observers":observers});
                socket
                    .send(tokio_tungstenite::tungstenite::Message::Text(
                        ack.to_string().into(),
                    ))
                    .await
                    .unwrap();
                if [REQUEST, RESPONSE, MEMORY_RECEIPT].contains(&id) {
                    for (index, (suffix, target, args)) in [
                        ("valid", "synthetic::collector", json!({})),
                        ("spawn", "harness::spawn", json!({})),
                        (
                            "forged",
                            "synthetic::collector",
                            json!({
                                "III_HARNESS_SYNTHETIC_GENERATION_CAPTURE":"1",
                                "capture_mode":"SyntheticIsolation",
                                "metadata":{"synthetic":true}
                            }),
                        ),
                    ]
                    .into_iter()
                    .enumerate()
                    {
                        // Even an unobserved fixture exercises the real added
                        // hook; those observers are removed before dispatch.
                        let observer_id = format!("{id}-{suffix}");
                        socket.send(tokio_tungstenite::tungstenite::Message::Text(json!({
                            "type":"observeradded", "function_id":id, "namespace":"default",
                            "revision":index + 2,
                            "observer":{"id":observer_id, "target":target, "args":args,
                                "filters":{}, "capture":["input","output","caller"], "on":"success"}
                        }).to_string().into())).await.unwrap();
                        if suffix == "forged"
                            && (!observed || (mode == "request_only" && id == RESPONSE))
                        {
                            socket.send(tokio_tungstenite::tungstenite::Message::Text(json!({
                                "type":"observerremoved", "function_id":id,
                                "namespace":"default", "revision":5, "id":format!("{id}-valid")
                            }).to_string().into())).await.unwrap();
                        }
                    }
                }
                continue;
            }
            if message["type"] != "invokefunction" {
                continue;
            }
            let function = message["function_id"].as_str().unwrap();
            seen.lock().unwrap().push(message.clone());
            if mode == "race" && function == REQUEST {
                // Remove the terminal reader after the request witness, before
                // acknowledging dispatch. The missing pair is unavailable.
                socket
                    .send(tokio_tungstenite::tungstenite::Message::Text(
                        json!({
                            "type":"observerremoved", "function_id":RESPONSE,
                            "namespace":"default", "revision":6, "id":format!("{RESPONSE}-valid")
                        })
                        .to_string()
                        .into(),
                    ))
                    .await
                    .unwrap();
            }
            let data = &message["data"];
            if function == "memory::hook::pre-generate" && mode == "origin_guard_failed" {
                socket.send(tokio_tungstenite::tungstenite::Message::Text(json!({
                    "type":"invocationresult", "invocation_id":message["invocation_id"],
                    "function_id":function, "error":{"code":"TEST_FAILURE","message":"bounded failure"}
                }).to_string().into())).await.unwrap();
                continue;
            }
            let result = match function {
                "memory::hook::pre-generate" if mode == "origin_guard_unbounded" => {
                    json!({"mutations":{"append_messages":[{"role":"user","content":"x".repeat(MAX_BYTES + 1)}]}})
                }
                "memory::hook::pre-generate" if mode == "origin_guard_unsupported" => {
                    json!({"mutations":{"append_messages":[{"role":"unsupported","content":{}}]}})
                }
                "memory::hook::pre-generate" | "synthetic::forger" if memory_fixture => {
                    json!({"mutations":{"append_messages":[
                        {"role":"user","content":[{"type":"text","text":MEMORY_TEXT}]}]},
                        "annotations":{"memory_bank":"synthetic-atlas"}})
                }
                "memory::hook::pre-generate" if mode == "origin_two" => {
                    json!({"mutations":{"append_messages":[
                    {"role":"user","content":[{"type":"text","text":"synthetic-turn-fact"}]},
                    {"role":"user","content":[{"type":"text","text":"synthetic-turn-fact"}]}]}})
                }
                "memory::hook::pre-generate" if mode.starts_with("origin_summary") => {
                    json!({"mutations":{"append_messages":[
                    {"role":"user","content":[{"type":"text","text":"synthetic-turn-fact\nother fact"}]}]}})
                }
                "context::count-tokens" => json!({"tokens":10}),
                "engine::functions::list" if mode.ends_with("owner_forged") => {
                    json!({"functions":[]})
                }
                // The engine hides `metadata.internal` functions, as Memory's
                // hook is, unless the caller asks for them.
                "engine::functions::list"
                    if mode.starts_with("origin_") && data["include_internal"] == true =>
                {
                    json!({"functions":[{"function_id":"memory::hook::pre-generate"}]})
                }
                "memory::hook::pre-generate" | "synthetic::forger" => {
                    json!({"mutations":{"append_messages":[
                    {"role":"user","content":[{"type":"text","text":"synthetic-turn-fact"}]}]},
                    "annotations":{"source":"memory","actor":"memory", "append_sources":[{"observer_id":"source-observer"}]}})
                }
                "session::append"
                    if mode.starts_with("origin_")
                        && data["custom"]["custom_type"] == crate::window::MODEL_NOTICE =>
                {
                    notices.push(json!({"entry_id":data["entry_id"], "custom":data["custom"]}));
                    json!({"entry_id":data["entry_id"]})
                }
                "session::messages"
                    if mode.starts_with("origin_") && data["after_entry_id"].is_null() =>
                {
                    let mut rows = vec![
                        json!({"entry_id":"synthetic-user", "message":{"role":"user","timestamp":0,
                        "content":[{"type":"text","text":if memory_fixture { MEMORY_TEXT } else { "synthetic-turn-fact" }}]}}),
                    ];
                    if mode.starts_with("origin_summary") && !notices.is_empty() {
                        let fixture = native_context_fixture()["assembly"].clone();
                        rows[0]["message"] = fixture["input"][0].clone();
                        rows.extend(notices.iter().cloned());
                        for (index, value) in fixture["input"]
                            .as_array()
                            .unwrap()
                            .iter()
                            .enumerate()
                            .skip(2)
                        {
                            rows.push(json!({"entry_id":format!("summary-input-{index}"),"message":value}));
                        }
                    } else if mode != "origin_memory_lost_notice" {
                        rows.extend(notices.iter().cloned());
                    }
                    json!({"messages":rows})
                }
                "context::assemble"
                    if mode.starts_with("origin_memory_summary") && generation_round > 0 =>
                {
                    let name = if mode.ends_with("noncontiguous") {
                        "memory-noncontiguous"
                    } else if mode.ends_with("basecopy") {
                        "memory-basecopy"
                    } else if mode.ends_with("reordered") {
                        "memory-reordered"
                    } else {
                        "memory-ordered"
                    };
                    let mut output = native_context_fixture()["renderers"][name].clone();
                    output["messages"] = json!([data["messages"][0].clone()]);
                    output["input_indices"] = json!([0]);
                    output["applied"] =
                        json!({"compacted":true,"summary":MEMORY_TEXT,"tail_start_index":0});
                    output["token_count"] = json!(10);
                    output["usable"] = json!(1000);
                    output["effective_max_output_tokens"] = json!(100);
                    if mode.ends_with("foreign") || mode.ends_with("late") {
                        output["summary_origin"]["summarized_indices"] = json!([0]);
                    }
                    generation_round += 1;
                    output
                }
                "context::assemble"
                    if mode.starts_with("origin_summary") && generation_round > 0 =>
                {
                    let fixture = native_context_fixture()["assembly"].clone();
                    let mut output = fixture["output"].clone();
                    assert_eq!(
                        data["messages"], fixture["input"],
                        "actual ContextClient request must match actual handler fixture"
                    );
                    if mode == "origin_summary_late" {
                        output["summary_origin"]["summarized_indices"] = json!([0]);
                    }
                    if mode == "origin_summary_wrongspan" {
                        output["summary_origin"]["span"]["byte_start"] = json!(0);
                    }
                    if [
                        "origin_summary_reordered",
                        "origin_summary_noncontiguous",
                        "origin_summary_basecopy",
                    ]
                    .contains(&mode.as_str())
                    {
                        let name = mode.strip_prefix("origin_").unwrap().replace('_', "-");
                        let rendered = native_context_fixture()["renderers"][&name].clone();
                        output["system_prompt"] = rendered["system_prompt"].clone();
                        output["summary_origin"]["span"] =
                            rendered["summary_origin"]["span"].clone();
                    }
                    generation_round += 1;
                    output
                }
                "context::assemble" if mode.starts_with("origin_") => {
                    let all = data["messages"].as_array().unwrap();
                    let selected: Vec<usize> = if generation_round == 0 {
                        (0..all.len()).collect()
                    } else if mode == "origin_removed" || mode == "origin_memory_removed" {
                        vec![0]
                    } else if mode == "origin_retained" || mode == "origin_memory_retained" {
                        vec![all.len() - 1]
                    } else {
                        (0..all.len()).collect()
                    };
                    generation_round += 1;
                    json!({"messages":selected.iter().map(|i| all[*i].clone()).collect::<Vec<_>>(),
                        "input_indices":selected, "token_count":10,"usable":1000,"effective_max_output_tokens":100})
                }
                "synthetic::reset" => {
                    stored_turn = initial_turn.clone();
                    Value::Null
                }
                "state::get" | "harness::state::get" if data["scope"] == "harness_turn" => {
                    stored_turn.clone()
                }
                "state::set" if data["scope"] == "harness_turn" => {
                    stored_turn = data["value"].clone();
                    Value::Null
                }
                "state::list" | "harness::state::list" => json!([]),
                "state::list_keys" => json!({"keys":[]}),
                "harness::state::compare-and-set" => json!({"swapped":true}),
                "session::get" => json!({"meta":{"session_id":server_session, "metadata":{}}}),
                "session::messages" if !data["after_entry_id"].is_null() => json!({"messages":[]}),
                "session::messages" => json!({"messages":[
                    {"entry_id":"synthetic-user", "message":{"role":"user", "timestamp":1,
                        "content":[{"type":"text", "text":"synthetic-turn-fact"}]}},
                    {"entry_id":crate::ids::assistant_entry_id("synthetic-turn", 7),
                        "origin":stale_origin, "message":empty_assistant("synthetic", "synthetic")}
                ]}),
                "session::append" => json!({"entry_id":data["entry_id"], "origin":stale_origin}),
                "session::update-message" => json!({"updated":true, "revision":8}),
                "session::set-status" => json!({"ok":true}),
                "context::assemble" => json!({
                    "messages":[{"role":"user", "timestamp":1,
                        "content":[{"type":"text", "text":"synthetic-turn-fact"}]}],
                    "token_count":10, "usable":1000, "effective_max_output_tokens":100
                }),
                "engine::channels::create" if mode == "before" => Value::Null,
                "engine::channels::create" => json!({
                    "writer":{"channel_id":"synthetic","access_key":"synthetic","direction":"write"},
                    "reader":{"channel_id":"synthetic","access_key":"synthetic","direction":"read"}
                }),
                "router::chat" if mode == "cancel" => continue,
                "router::chat" if mode == "error" => {
                    json!({"ok":false,"error":{"message":"synthetic failure"}})
                }
                "router::chat" => json!({"ok":true}),
                _ => Value::Null,
            };
            if memory_fixture
                && ["memory::hook::pre-generate", "synthetic::forger"].contains(&function)
            {
                // Exact loopback return bytes, separate from the producer's certificate.
                seen.lock()
                    .unwrap()
                    .push(json!({"type":"loopback-hook-output",
                    "function_id":"fixture::hook-output", "input":data, "output":result}));
            }
            if !message["invocation_id"].is_null() {
                let reply = json!({"type":"invocationresult","invocation_id":message["invocation_id"],
                    "function_id":function,"result":result});
                socket
                    .send(tokio_tungstenite::tungstenite::Message::Text(
                        reply.to_string().into(),
                    ))
                    .await
                    .unwrap();
            }
        }
        streams.abort();
    });
    let iii = Arc::new(iii_sdk::register_worker(
        &url,
        iii_sdk::InitOptions::default(),
    ));
    ready_rx.await.unwrap();
    let events = crate::events::TurnEvents::register_with_capture_mode(&iii, capture_mode);
    // Capture events, and so their observers, exist only in capture mode.
    if capture_mode == CaptureMode::SyntheticIsolation {
        tokio::time::timeout(std::time::Duration::from_secs(5), registered_rx)
            .await
            .expect("synthetic observation handshake timed out")
            .unwrap();
    }
    // A remote barrier ensures registration acknowledgements were consumed.
    let _ = iii
        .call(iii_sdk::CallRequest {
            function_id: "synthetic::barrier".into(),
            payload: Value::Null,
            action: None,
            timeout_ms: Some(2000),
        })
        .await;
    let mut router = RouterClient::new(iii.clone(), 2000, 0);
    router.capture_mode = capture_mode;
    let mut ids = Vec::new();
    let deps = crate::deps::Deps::new(
        iii.clone(),
        Arc::new(tokio::sync::RwLock::new(Arc::new(
            crate::config::WorkerConfig {
                session_timeout_ms: 2000,
                router_timeout_ms: 2000,
                stream_coalesce_ms: 0,
                ..Default::default()
            },
        ))),
        crate::discovery::new_cell(),
        crate::skills::new_cell(),
        events,
        crate::hooks::HookRegistry::register(&iii),
    );
    let mode = outcome_mode;
    // HookRegistry registration is enqueued after the earlier event barrier.
    // Drain its acknowledgement too before inspecting actual SDK observers.
    iii.call(CallRequest {
        function_id: "synthetic::barrier".into(),
        payload: Value::Null,
        action: None,
        timeout_ms: Some(2000),
    })
    .await
    .unwrap();
    for fact in ["Known full fact", "Unrelated summary", "Known full fact"] {
        if mode.starts_with("origin_guard_") {
            let input = json!({"point":"pre_generate", "session_id":session_id,
                "turn_id":"guard-turn", "step":19, "depth":0,
                "_caller_worker_id":"harness", "metadata":{"internal":true},
                "generate":{"messages":[]}});
            TEST_CAPTURE_MODE
                .scope(
                    capture_mode,
                    crate::hooks::runner::test_memory_invocation(
                        iii.clone(),
                        input,
                        mode == "origin_guard_external",
                        mode == "origin_guard_absent",
                        if mode == "origin_guard_wrongpoint" {
                            crate::hooks::HookPoint::PreTurn
                        } else {
                            crate::hooks::HookPoint::PreGenerate
                        },
                    ),
                )
                .await;
            break;
        }
        if mode == "current_update" || mode.starts_with("origin_") {
            iii.call(CallRequest {
                function_id: "synthetic::reset".into(),
                payload: Value::Null,
                action: None,
                timeout_ms: Some(2000),
            })
            .await
            .unwrap();
            let result = TEST_CAPTURE_MODE
                .scope(
                    capture_mode,
                    crate::turn_loop::run_step(
                        &deps,
                        crate::turn_loop::TurnStepPayload {
                            session_id: session_id.clone(),
                            turn_id: turn_id.into(),
                            step,
                            depth: 0,
                            message_preview: None,
                        },
                    ),
                )
                .await
                .unwrap();
            assert_eq!(result.status, crate::types::turn::TurnStatus::Completed);
            continue;
        }
        let (tx, rx) = watch::channel(false);
        let mut input = params(fact);
        // Caller-controlled env-like JSON must not affect process capability.
        input.provider_options = Some(json!({
            "III_HARNESS_SYNTHETIC_GENERATION_CAPTURE":"1",
            "metadata":{"capture_mode":"SyntheticIsolation"},
            "secret":"synthetic-caller-secret"
        }));
        let future = router.chat(input, &Sink, rx);
        let outcome = if mode == "cancel" {
            tokio::pin!(future);
            tokio::select! {
                result = &mut future => result,
                _ = tokio::time::sleep(std::time::Duration::from_millis(30)) => {
                    tx.send(true).unwrap(); future.await
                }
            }
        } else {
            future.await
        };
        if mode == "before" {
            assert!(outcome.is_err());
        } else {
            let outcome = outcome.unwrap();
            assert_eq!(outcome.ok, !["error", "cancel"].contains(&mode.as_str()));
            ids.extend(outcome.generation_id);
        }
    }
    // Void enqueue completion is not remote delivery: drain the same SDK
    // connection with an acknowledged barrier before inspecting the collector.
    let _ = iii
        .call(iii_sdk::CallRequest {
            function_id: "synthetic::barrier".into(),
            payload: Value::Null,
            action: None,
            timeout_ms: Some(2000),
        })
        .await;
    drop(router);
    iii.shutdown();
    server.abort();
    let calls = calls.lock().unwrap().clone();
    let registrations = registrations.lock().unwrap().clone();
    (calls, registrations, ids)
}

#[tokio::test]
async fn synthetic_memory_no_emission_guards() {
    for mode in [
        "origin_guard_positive",
        "origin_guard_external",
        "origin_guard_absent",
        "origin_guard_wrongpoint",
        "origin_guard_failed",
        "origin_guard_unsupported",
        "origin_guard_unbounded",
    ] {
        let (calls, _, _) = loopback(true, mode).await;
        assert_eq!(
            calls
                .iter()
                .filter(|c| c["function_id"] == MEMORY_RECEIPT)
                .count(),
            usize::from(mode == "origin_guard_positive"),
            "{mode}"
        );
        let invoked = calls
            .iter()
            .filter(|c| c["function_id"] == "memory::hook::pre-generate")
            .count();
        assert_eq!(
            invoked,
            usize::from(mode != "origin_guard_absent"),
            "guard must execute the real path: {mode}"
        );
    }
}

#[tokio::test]
async fn synthetic_memory_two_append_receipt_ordinals() {
    let (calls, _, _) = loopback(true, "origin_two").await;
    let receipts: Vec<_> = calls
        .iter()
        .filter(|c| c["function_id"] == MEMORY_RECEIPT)
        .collect();
    let requests: Vec<_> = calls
        .iter()
        .filter(|c| c["function_id"] == REQUEST)
        .collect();
    assert_eq!((receipts.len(), requests.len()), (3, 3));
    for (receipt, request) in receipts.iter().zip(&requests) {
        let appends = receipt["data"]["appends"].as_array().unwrap();
        let slots = request["data"]["sources"].as_array().unwrap();
        assert_eq!((appends.len(), slots.len()), (2, 2));
        for ordinal in 0..2 {
            assert_eq!(appends[ordinal]["append_ordinal"], ordinal);
            assert_eq!(slots[ordinal]["append_ordinal"], ordinal);
            assert_eq!(
                appends[ordinal]["message_sha256"],
                slots[ordinal]["message_sha256"]
            );
        }
        assert_ne!(slots[0]["entry_id"], slots[1]["entry_id"]);
        assert_eq!(appends[0]["message_sha256"], appends[1]["message_sha256"]);
    }
}

#[test]
fn synthetic_memory_utf8_span_boundaries() {
    let system = "naïve prefix\n\nRésumé 🦀";
    let start = system.find("Résumé").unwrap();
    let good = SummarySpan {
        byte_start: start,
        byte_end: system.len(),
        summary_sha256: raw_digest(&system[start..]),
        system_sha256: raw_digest(system),
    };
    assert_eq!(valid_span(system, &good), Some("Résumé 🦀"));
    for (start, end) in [
        (start + 2, system.len()),
        (start, system.len() - 1),
        (start, system.len() + 1),
        (system.len() + 1, system.len()),
        (system.len(), start),
    ] {
        let mut bad = good.clone();
        bad.byte_start = start;
        bad.byte_end = end;
        assert!(valid_span(system, &bad).is_none());
    }
    for whole in [false, true] {
        let mut bad = good.clone();
        if whole {
            bad.system_sha256 = "0".repeat(64);
        } else {
            bad.summary_sha256 = "0".repeat(64);
        }
        assert!(valid_span(system, &bad).is_none());
    }
}

// Each thread owns a fresh process-local ledger seam. Production methods and
// capacities remain unchanged, and no other test's authority is reset/evicted.
#[test]
fn synthetic_memory_native_ledger_equality_eviction_and_fresh_authority() {
    struct Isolated;
    impl Drop for Isolated {
        fn drop(&mut self) {
            TEST_SLOT_LEDGER.with(|l| *l.borrow_mut() = None);
            TEST_SUMMARY_LEDGER.with(|l| *l.borrow_mut() = None);
        }
    }
    TEST_SLOT_LEDGER.with(|l| *l.borrow_mut() = Some(Default::default()));
    TEST_SUMMARY_LEDGER.with(|l| *l.borrow_mut() = Some(Default::default()));
    let _isolated = Isolated;
    let value = json!({"role":"user", "timestamp":0, "content":[{"type":"text","text":"Résumé 🦀\nother fact"}]});
    let slot = SourceSlot {
        message_index: 0,
        entry_id: "native-entry".into(),
        observer_id: "native-observer".into(),
        append_ordinal: 2,
        message_sha256: message_digest(&value).unwrap(),
        source: "fresh_memory".into(),
    };
    let session = "native-ledger-session";
    assert!(replay_slot(session, &slot.entry_id, &value, 4).is_none());
    remember(session, &slot);
    let replay = replay_slot(session, &slot.entry_id, &value, 4).unwrap();
    assert_eq!(replay.message_index, 4);
    assert_eq!(replay.source, "replay_memory");
    assert_eq!(replay.observer_id, slot.observer_id);
    assert_eq!(replay.append_ordinal, 2);
    for (s, e, body) in [
        ("fresh-session", slot.entry_id.as_str(), value.clone()),
        (session, "wrong-entry", value.clone()),
        (
            session,
            slot.entry_id.as_str(),
            json!({"role":"user","content":"changed"}),
        ),
    ] {
        assert!(replay_slot(s, e, &body, 0).is_none());
    }
    let text = "Résumé 🦀\nother fact";
    let origin = AssemblySummary {
        assembly_id: "native-assembly".into(),
        summarized_indices: Some(vec![0]),
        span: SummarySpan {
            byte_start: 0,
            byte_end: text.len(),
            summary_sha256: raw_digest(text),
            system_sha256: raw_digest(text),
        },
    };
    let candidate = vec![(
        slot.entry_id.clone(),
        serde_json::from_value(value.clone()).unwrap(),
    )];
    let witness = bind_summary(session, &origin, text, &candidate, None).unwrap();
    assert_eq!(witness.inputs.len(), 1);
    assert_eq!(witness.lines.len(), 2);
    assert_eq!(witness.inputs[0].message_sha256, slot.message_sha256);
    for (s, c) in [
        ("fresh-session", candidate.clone()),
        (
            session,
            vec![("wrong-entry".into(), candidate[0].1.clone())],
        ),
        (
            session,
            vec![(
                slot.entry_id.clone(),
                crate::types::AgentMessage::user_text("changed"),
            )],
        ),
    ] {
        assert!(bind_summary(s, &origin, text, &c, None).is_none());
    }
    let mut previous = origin.clone();
    previous.summarized_indices = None;
    assert!(
        bind_summary(
            session,
            &previous,
            text,
            &[],
            Some(("summary-entry", &origin.span.summary_sha256))
        )
        .is_none()
    );
    remember_summary(session, "summary-entry", &witness);
    assert!(
        bind_summary(
            session,
            &previous,
            text,
            &[],
            Some(("summary-entry", &origin.span.summary_sha256))
        )
        .is_some()
    );
    for (s, entry, digest) in [
        (
            "fresh-session",
            "summary-entry",
            origin.span.summary_sha256.as_str(),
        ),
        (session, "wrong-entry", origin.span.summary_sha256.as_str()),
        (session, "summary-entry", "wrong-digest"),
    ] {
        assert!(bind_summary(s, &previous, text, &[], Some((entry, digest))).is_none());
    }
    for i in 0..MAX_LINES {
        let mut filler = slot.clone();
        filler.entry_id = format!("bounded-entry-{i}");
        remember(session, &filler);
        remember_summary(session, &format!("bounded-summary-{i}"), &witness);
    }
    assert_eq!(with_slot_ledger(|l| l.len()), Some(MAX_LINES));
    assert_eq!(with_summary_ledger(|l| l.len()), Some(MAX_LINES));
    assert!(replay_slot(session, &slot.entry_id, &value, 0).is_none());
    assert!(bind_summary(session, &origin, text, &candidate, None).is_none());
    assert!(
        bind_summary(
            session,
            &previous,
            text,
            &[],
            Some(("summary-entry", &origin.span.summary_sha256))
        )
        .is_none()
    );
    std::thread::spawn(move || {
        TEST_SLOT_LEDGER.with(|l| *l.borrow_mut() = Some(Default::default()));
        TEST_SUMMARY_LEDGER.with(|l| *l.borrow_mut() = Some(Default::default()));
        let _fresh = Isolated;
        assert!(replay_slot(session, &slot.entry_id, &value, 0).is_none());
        assert!(
            bind_summary(
                session,
                &previous,
                text,
                &[],
                Some(("summary-entry", &origin.span.summary_sha256))
            )
            .is_none()
        );
    })
    .join()
    .unwrap();
}

#[test]
fn summary_replay_keeps_certified_groups_split_by_unrelated_text() {
    struct Isolated;
    impl Drop for Isolated {
        fn drop(&mut self) {
            TEST_SLOT_LEDGER.with(|l| *l.borrow_mut() = None);
            TEST_SUMMARY_LEDGER.with(|l| *l.borrow_mut() = None);
        }
    }
    TEST_SLOT_LEDGER.with(|l| *l.borrow_mut() = Some(Default::default()));
    TEST_SUMMARY_LEDGER.with(|l| *l.borrow_mut() = Some(Default::default()));
    let _isolated = Isolated;
    let session = "split-groups-session";
    let candidate: Vec<(String, crate::types::AgentMessage)> =
        ["alpha fact\nbeta fact", "gamma fact"]
            .into_iter()
            .enumerate()
            .map(|(i, text)| {
                let value =
                    json!({"role":"user", "timestamp":0, "content":[{"type":"text","text":text}]});
                let entry_id = format!("split-entry-{i}");
                remember(
                    session,
                    &SourceSlot {
                        message_index: i,
                        entry_id: entry_id.clone(),
                        observer_id: "split-observer".into(),
                        append_ordinal: i,
                        message_sha256: message_digest(&value).unwrap(),
                        source: "fresh_memory".into(),
                    },
                );
                (entry_id, serde_json::from_value(value).unwrap())
            })
            .collect();
    let summary = |text: &str, summarized_indices| AssemblySummary {
        assembly_id: "split-assembly".into(),
        summarized_indices,
        span: SummarySpan {
            byte_start: 0,
            byte_end: text.len(),
            summary_sha256: raw_digest(text),
            system_sha256: raw_digest(text),
        },
    };
    let certify = |text: &str| {
        bind_summary(
            session,
            &summary(text, Some(vec![0, 1])),
            text,
            &candidate,
            None,
        )
    };
    // A later step renders `text` with nothing newly summarized, replaying the
    // witness stored for the earlier summary `prior`.
    let replay = |entry: &str, prior: &str, text: &str| {
        let digest = raw_digest(prior);
        bind_summary(
            session,
            &summary(text, None),
            text,
            &[],
            Some((entry, &digest)),
        )
    };
    let lines = |witness: &SummaryWitness| witness.lines.iter().map(|l| l.line).collect::<Vec<_>>();
    // Both Memory inputs appear verbatim, with a line of the summary's own between.
    let text = "alpha fact\nbeta fact\nThe user moved on.\ngamma fact";
    let witness = certify(text).unwrap();
    assert_eq!(lines(&witness), [0, 1, 3]);
    remember_summary(session, "split-summary", &witness);
    let replayed =
        replay("split-summary", text, text).expect("the replayed summary keeps its certificate");
    assert_eq!(lines(&replayed), [0, 1, 3]);
    assert_eq!(replayed.inputs.len(), 2);

    // Groups certified side by side stay separate groups when a later
    // compaction puts unrelated text between them.
    let adjacent = "alpha fact\nbeta fact\ngamma fact";
    let adjacent_witness = certify(adjacent).unwrap();
    assert_eq!(lines(&adjacent_witness), [0, 1, 2]);
    remember_summary(session, "adjacent-summary", &adjacent_witness);
    let replayed =
        replay("adjacent-summary", adjacent, text).expect("adjacent groups still bind once split");
    assert_eq!(lines(&replayed), [0, 1, 3]);
    assert_eq!(replayed.inputs.len(), 2);
    // A replay keeps the boundaries, so the next compaction can split them too.
    let again = replay("adjacent-summary", adjacent, adjacent).unwrap();
    remember_summary(session, "adjacent-again", &again);
    assert_eq!(
        lines(&replay("adjacent-again", adjacent, text).unwrap()),
        [0, 1, 3]
    );
    // A group still binds only whole and in order: torn apart, only gamma binds.
    let torn = "alpha fact\nThe user moved on.\nbeta fact\ngamma fact";
    assert_eq!(
        lines(&replay("adjacent-summary", adjacent, torn).unwrap()),
        [3]
    );

    // The same notices summarized again beside the replayed witness: each
    // group is kept once, so repeated compactions cannot grow the witness.
    let digest = raw_digest(text);
    let both = bind_summary(
        session,
        &summary(text, Some(vec![0, 1])),
        text,
        &candidate,
        Some(("split-summary", &digest)),
    )
    .unwrap();
    assert_eq!(lines(&both), [0, 1, 3]);
    assert_eq!(both.groups.len(), 2);
}

